package corpus.rethrowpolicy

fun invokeOrPropagate(action: () -> String): String = try {
    action()
} catch (failure: java.io.IOException) {
    throw (failure)
}

package corpus.rethrowpolicy

fun invokeOrRecover(action: () -> String, recover: (IllegalStateException) -> String): String = try {
    action()
} catch (failure: java.io.IOException) {
    throw failure
} catch (failure: IllegalStateException) {
    recover(failure)
}

package corpus.rethrowpolicy

